using FluentValidation;namespace SchoolERP.Application.Features.SchoolCalendar;public sealed class CalendarEventRequestValidator:AbstractValidator<CalendarEventRequest>{public CalendarEventRequestValidator(){RuleFor(x=>x.Title).NotEmpty().MaximumLength(200);RuleFor(x=>x.Code).MaximumLength(50).Matches("^[A-Za-z0-9]+(?:[-_][A-Za-z0-9]+)*$").When(x=>!string.IsNullOrWhiteSpace(x.Code));RuleFor(x=>x.Type).IsInEnum();RuleFor(x=>x.EndDate).GreaterThanOrEqualTo(x=>x.StartDate);RuleFor(x=>x.ColorHex).Matches("^#[0-9A-Fa-f]{6}$").When(x=>!string.IsNullOrWhiteSpace(x.ColorHex));RuleFor(x=>x.Location).MaximumLength(200);RuleFor(x=>x.Description).MaximumLength(1000);RuleFor(x=>x.Recurrence).IsInEnum();RuleFor(x=>x).Must(x=>x.IsAllDay||x.StartDate==x.EndDate&&x.StartTime.HasValue&&x.EndTime.HasValue&&x.EndTime>x.StartTime).WithMessage("SchoolCalendar.InvalidTimeRange");}}
